'use strict';
let commandSelection=0,commandItems=[],commandTarget='market',companySearchTimer,companySearchVersion=0,companySearchState='';const companySearchCache=new Map();
function paletteResults(query,records=signalData){
 const q=query.trim().toLowerCase().replace(/^\$/,''),match=s=>!q||q.split(/\s+/).every(word=>s.toLowerCase().includes(word));
 const commands=[["Research map",'map','Detective connections why this stock now evidence thesis'],["poor’s research",'daily','Daily research TLDR politicians swing trading briefs'],['Connect the dots','research','SEC insiders policy contracts source evidence timeline'],['Position planner','risk','Shares entry stop target position sizing risk reward'],['Sector comparison','sector','Relative strength ETF benchmark'],['Market context','macro','Bonds credit dollar oil rates'],['Short swing horizon','short-swing','2 to 20 days technical indicators RSI ATR'],['Multi-week horizon','position-swing','Weeks months technical indicators RSI ATR'],['Home','home','Overview latest purchases ETFs popular stocks bookmarks'],['Terminal','market','Stocks charts prices'],['Political trades','trades','Transactions disclosures'],['Politicians','politicians','Track record performance rankings filters'],['Politician watchlist','watchlist','Following saved people'],['Alerts','alerts','Rules notifications'],['Sources','sources','Coverage freshness methodology'],['Shared buys','clusters','Multiple politicians buying same stock'],['Create stock alert','alert','Price disclosure cluster rule']].map(([label,key,keywords])=>({kind:'command',key,label,detail:'Action',search:label+' '+keywords}));
 commands.push({kind:'connected',key:'help',label:'Keyboard shortcuts',detail:'?',search:'keyboard shortcuts help guide'},{kind:'connected',key:'stock-map',label:'Current stock map',detail:'Ctrl M',search:'current stock map connections'},{kind:'connected',key:'stock-trades',label:'Current stock trades',detail:'Related page',search:'current stock political trades purchases sales'},{kind:'connected',key:'profile',label:'Current politician profile',detail:'Profile & timeline',search:'current politician profile timeline'},{kind:'connected',key:'briefs',label:'Current stock research',detail:'Related briefs',search:'current stock research articles'});
 commands.push({kind:'chart',key:'priceOnly',label:'Price only chart',detail:'Hide all overlays',search:'clean chart price only hide all overlays'});
 commands.push(...[['buys','Politician buy markers',showBuyMarkers],['sales','Politician sale markers',showSaleMarkers],['labels','Chart names and returns',showChartLabels],['activity','Chart activity details',showChartActivity],['disclosures','Disclosure markers',showDisclosureMarkers],['benchmark','SPY comparison',showBenchmark]].map(([key,label,on])=>({kind:'chart',key,label:(on?'Hide ':'Show ')+label,detail:'Chart overlay · '+(on?'on':'off'),search:label+' toggle show hide on off chart'})));
 const people=[...new Set([...Object.keys(ROSTER),...signalData.map(r=>r.person)])].sort().map(person=>({kind:'person',key:person,label:person,detail:politicianTitle(person)+' · Research map',search:person+' '+politicianTitle(person)}));
 const stocks=new Map();for(const r of records)if(tickerValid(r.ticker)&&!stocks.has(r.ticker))stocks.set(r.ticker,{kind:'stock',key:r.ticker,label:r.ticker,detail:r.company,search:r.ticker+' '+r.company});
 for(const [ticker,p] of Object.entries(PRICES))if(tickerValid(ticker)&&p.name&&!stocks.has(ticker))stocks.set(ticker,{kind:'stock',key:ticker,label:ticker,detail:p.name,search:ticker+' '+p.name});
 for(const r of companySearchCache.get(q)||[])stocks.set(r.symbol,{kind:'stock',key:r.symbol,label:r.symbol+' · '+r.name,detail:[r.exchange,r.type==='ETF'?'ETF':'Stock'].filter(Boolean).join(' · '),search:r.symbol+' '+r.name});
 const found=[...commands,...people,...stocks.values(),...(typeof visibleCommandItems!=='undefined'?visibleCommandItems:[])].filter(item=>match(item.search)).sort((a,b)=>Number(b.label.toLowerCase()===q)-Number(a.label.toLowerCase()===q));
 const ticker=q.replace(/^\$/,'').toUpperCase();if(q&&(query.trim().startsWith('$')||query.trim()===ticker)&&tickerValid(ticker)&&!found.some(i=>i.kind==='stock'&&i.key===ticker))found.push({kind:'stock',key:ticker,label:'Open '+ticker,detail:'Look up stock ticker'});
 return found.slice(0,30);
}
function renderCommands(){commandItems=paletteResults($('#commandInput').value);commandSelection=0;$('#commandResults').innerHTML=commandItems.map((item,i)=>`<div id="command-option-${i}" role="option" aria-selected="false" data-command-index="${i}" class="command-option"><span><strong>${esc(item.label)}</strong><small>${esc(item.detail)}</small></span><span class="command-kind">${item.kind==='stock'?'Stock':item.kind==='person'?'Person':'Go'}</span></div>`).join('')||'<p class="command-empty">No matches yet. Search a company, ticker, politician or page.</p>';$('#commandStatus').textContent=companySearchState||commandItems.length+' results';selectCommand(0)}
function selectCommand(index){commandSelection=Math.max(0,Math.min(index,commandItems.length-1));$$('[data-command-index]').forEach((el,i)=>el.setAttribute('aria-selected',String(i===commandSelection)));const selected=$('#command-option-'+commandSelection);if(selected){$('#commandInput').setAttribute('aria-activedescendant',selected.id);selected.scrollIntoView({block:'nearest'})}else $('#commandInput').removeAttribute('aria-activedescendant')}
async function searchCommandCompanies(){clearTimeout(companySearchTimer);const version=++companySearchVersion,q=$('#commandInput').value.trim().toLowerCase().replace(/^\$/,'');companySearchState='';renderCommands();if(q.length<2||q.length>80||companySearchCache.has(q))return;companySearchState='Searching companies…';$('#commandStatus').textContent=companySearchState;companySearchTimer=setTimeout(async()=>{try{const r=await getLiveJSON('/api/search?q='+encodeURIComponent(q));if(!r.value?.quotes)throw Error();companySearchCache.set(q,r.value.quotes);if(version!==companySearchVersion)return;companySearchState=r.stale?'Cached company matches':'';renderCommands()}catch{if(version!==companySearchVersion)return;companySearchState='Company search unavailable · local matches shown';renderCommands()}},250)}
function openCommands(target='market'){if($('#commandPalette').open)return;if(document.querySelector('dialog[open]'))return;if(typeof collectVisibleCommands==='function')visibleCommandItems=collectVisibleCommands();commandTarget=target==='map'?'map':'market';companySearchVersion++;companySearchState='';$('#commandInput').value='';$('#commandPalette').showModal();renderCommands();$('#commandInput').focus()}
function runCommand(index){const item=commandItems[index];if(!item)return;$('#commandPalette').close();if(item.kind==='control'){runVisibleCommand(item);return}if(item.kind==='connected'){goConnected(item.key);return}if(item.kind==='chart'){const enabled=chartOptions()[item.key];setChartOption(item.key,!enabled);changeView('market');return}if(item.kind==='stock'){if(commandTarget==='map')openResearchMap(item.key);else openStock(item.key);return}if(item.kind==='person'){openPeopleMap(item.key);return}if(item.key==='map'){goConnected('map');return}if(['research','risk','sector'].includes(item.key)){changeView('market');const el=$('#'+({research:'researchPanel',risk:'riskPanel',sector:'sectorSelect'}[item.key]));if(item.key==='risk')el.open=true;el.scrollIntoView({block:'start'});return}if(item.key==='macro'){changeView('home');$('#marketContext').scrollIntoView({block:'start'});return}if(['short-swing','position-swing'].includes(item.key)){setSwingHorizon(item.key==='short-swing'?'short':'position');changeView('market');return}if(item.key==='alert'){openAlertForm();return}if(item.key==='clusters'){clear();scope='clusters';$$('[data-scope]').forEach(b=>b.classList.toggle('selected',b.dataset.scope===scope));changeView('trades');renderRows();return}changeView(item.key)}
if(typeof window!=='undefined'){
 $('#commandButton').onclick=openCommands;$('#commandClose').onclick=()=>$('#commandPalette').close();
 $('#commandInput').addEventListener('input',searchCommandCompanies);
 $('#commandInput').addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();selectCommand((commandSelection+(e.key==='ArrowDown'?1:-1)+commandItems.length)%Math.max(1,commandItems.length))}else if(e.key==='Enter'){e.preventDefault();runCommand(commandSelection)}});
 $('#commandResults').addEventListener('click',e=>{const row=e.target.closest('[data-command-index]');if(row)runCommand(Number(row.dataset.commandIndex))});
 $('#commandPalette').addEventListener('click',e=>{if(e.target===$('#commandPalette')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&!e.altKey&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#commandPalette').open)$('#commandPalette').close();else openCommands()}});
}
